script_body:
param([bool]$IncludeNetwork = $true)
$inventory = [ordered]@{
  computerName = $env:COMPUTERNAME
  os = (Get-CimInstance Win32_OperatingSystem).Caption
  serialNumber = (Get-CimInstance Win32_BIOS).SerialNumber
}
if ($IncludeNetwork) {
  $inventory.networkAdapters = Get-CimInstance Win32_NetworkAdapterConfiguration | Where-Object { $_.IPEnabled } | Select-Object Description,IPAddress,MACAddress
}
$inventory | ConvertTo-Json -Depth 4
